class LedgerError(Exception):
    pass


class InsufficientFunds(LedgerError):
    pass


class Ledger:
    def __init__(self):
        self.accounts = {}
        self.history = {}

    def open_account(self, account_id: str) -> None:
        if not account_id:
            raise ValueError("Account ID cannot be empty")
        if account_id in self.accounts:
            raise LedgerError("Account already open")
        self.accounts[account_id] = 0
        self.history[account_id] = []

    def deposit(self, account_id: str, amount: int) -> None:
        self._validate_account(account_id)
        self._validate_amount(amount)
        self.accounts[account_id] += amount
        self.history[account_id].append(("deposit", amount))

    def withdraw(self, account_id: str, amount: int) -> None:
        self._validate_account(account_id)
        self._validate_amount(amount)
        if self.accounts[account_id] < amount:
            raise InsufficientFunds
        self.accounts[account_id] -= amount
        self.history[account_id].append(("withdrawal", amount))

    def transfer(self, from_id: str, to_id: str, amount: int) -> None:
        self._validate_account(from_id)
        self._validate_account(to_id)
        if from_id == to_id:
            raise ValueError("Cannot transfer to the same account")
        self._validate_amount(amount)
        if self.accounts[from_id] < amount:
            raise InsufficientFunds
        self.accounts[from_id] -= amount
        self.accounts[to_id] += amount
        self.history[from_id].append(("transfer_out", amount))
        self.history[to_id].append(("transfer_in", amount))

    def get_balance(self, account_id: str) -> int:
        self._validate_account(account_id)
        return self.accounts[account_id]

    def get_history(self, account_id: str) -> list[tuple[str, int]]:
        self._validate_account(account_id)
        return self.history[account_id]

    def get_accounts(self) -> list[str]:
        return list(self.accounts.keys())

    def _validate_account(self, account_id: str) -> None:
        if account_id not in self.accounts:
            raise KeyError("Account not open")

    def _validate_amount(self, amount: int) -> None:
        if not isinstance(amount, int) or amount <= 0:
            raise ValueError("Amount must be a positive integer")
