    """Base exception for ledger errors."""
    pass


class InsufficientFunds(LedgerError):
    """Exception raised when attempting to withdraw more than the available balance."""
    pass


class Ledger:
    def __init__(self):
        self._accounts = {}
        self._history = {}

    def open_account(self, account_id: str) -> None:
        if not account_id:
            raise ValueError("Account ID cannot be empty")
        if account_id in self._accounts:
            raise LedgerError("Account already open")
        self._accounts[account_id] = 0
        self._history[account_id] = []

    def deposit(self, account_id: str, amount: int) -> None:
        self._validate_account(account_id)
        self._validate_amount(amount)
        self._accounts[account_id] += amount
        self._history[account_id].append(("deposit", amount))

    def withdraw(self, account_id: str, amount: int) -> None:
        self._validate_account(account_id)
        self._validate_amount(amount)
        if amount > self._accounts[account_id]:
            raise InsufficientFunds("Insufficient funds")
        self._accounts[account_id] -= amount
        self._history[account_id].append(("withdrawal", amount))

    def transfer(self, from_id: str, to_id: str, amount: int) -> None:
        self._validate_account(from_id)
        self._validate_account(to_id)
        if from_id == to_id:
            raise ValueError("Cannot transfer to the same account")
        self._validate_amount(amount)
        if amount > self._accounts[from_id]:
            raise InsufficientFunds("Insufficient funds")
        self._accounts[from_id] -= amount
        self._history[from_id].append(("transfer_out", amount))
        self._accounts[to_id] += amount
        self._history[to_id].append(("transfer_in", amount))

    def get_balance(self, account_id: str) -> int:
        self._validate_account(account_id)
