    def get_vehicles(self, level_id: str) -> list[str]:
        if level_id not in self.levels:
            raise KeyError("Level not found")
        return self.levels[level_id]['vehicles']

    def get_levels(self) -> list[str]:
        return list(self.levels.keys())
